def compute(vars):
    stock_index = vars["v1"]
    sp500_index = vars["v2"]
    initial_index = 100.0

    stock_return_pct = stock_index - initial_index
    sp500_return_pct = sp500_index - initial_index
    difference_pct = stock_return_pct - sp500_return_pct

    return {
        "value": difference_pct,
        "trace": {
            "stock_return_pct": stock_return_pct,
            "sp500_return_pct": sp500_return_pct,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
